/* Convenience: initialize from one of the generated datas. */
static inline int btn_init_committed(BinaryTransformNetwork *btn, const char *name) {
    const FrozenBTNData *d = NULL;
    if (strcmp(name, "hex_value") == 0) d = &frozen_hex_value_data;
    if (strcmp(name, "increment") == 0) d = &frozen_increment_data;
    if (strcmp(name, "combine") == 0) d = &frozen_combine_data;
    if (strcmp(name, "split") == 0) d = &frozen_split_data;
    if (strcmp(name, "dec_value") == 0) d = &frozen_dec_value_data;
    if (strcmp(name, "dec_to_symbol") == 0) d = &frozen_dec_to_symbol_data;
    if (strcmp(name, "dec_full_add") == 0) d = &frozen_dec_full_add_data;
    if (strcmp(name, "dec_swap_ab") == 0) d = &frozen_dec_swap_ab_data;
    if (strcmp(name, "dec_add_unit") == 0) d = &frozen_dec_add_unit_data;
    if (!d) return -1;
    return btn_init_frozen(btn, d);
}

